package ca.yorku.eecs3311.coursepilot.application.service;
import ca.yorku.eecs3311.coursepilot.application.ai.*; import ca.yorku.eecs3311.coursepilot.application.dto.*; import ca.yorku.eecs3311.coursepilot.domain.model.*; import ca.yorku.eecs3311.coursepilot.domain.repository.*; import jakarta.transaction.Transactional; import org.springframework.stereotype.Service; import java.util.*; import java.util.stream.Collectors;
@Service public class QuizAttemptService {
 private final QuizRepository quizzes; private final QuizAttemptRepository attempts; private final LlmClient llm; private final PromptBuilder prompts; private final StructuredResponseParser parser; private final GroundingContextBuilder builder; private final DocumentChunkRepository chunks;
 public QuizAttemptService(QuizRepository q,QuizAttemptRepository a,LlmClient l,PromptBuilder p,StructuredResponseParser s,GroundingContextBuilder b,DocumentChunkRepository c){quizzes=q;attempts=a;llm=l;prompts=p;parser=s;builder=b;chunks=c;}
 @org.springframework.transaction.annotation.Transactional(readOnly=true) public List<QuizResponseDto> list(Long courseId){return quizzes.findByCourseId(courseId).stream().map(QuizResponseDto::from).toList();}
 @org.springframework.transaction.annotation.Transactional(readOnly=true) public QuizResponseDto get(Long courseId,Long quizId){return QuizResponseDto.from(quizzes.findOwned(quizId,courseId).orElseThrow(()->new IllegalArgumentException("Quiz was not found for this course.")));}
 @Transactional public QuizAttemptResult submit(Long courseId,Long quizId,Map<Long,String> answers){Quiz quiz=quizzes.findOwned(quizId,courseId).orElseThrow(()->new IllegalArgumentException("Quiz was not found for this course."));QuizAttempt attempt=new QuizAttempt(quiz,quiz.getQuestions().size());List<QuizAttemptResult.AnswerResult> result=new ArrayList<>();int correct=0;for(QuizQuestion q:quiz.getQuestions()){String answer=answers==null?"":Objects.toString(answers.get(q.getId()),"").trim();Grading g=grade(q,answer);if(g.correct())correct++;attempt.addResponse(new QuizResponse(attempt,q,answer,g.correct(),g.feedback()));result.add(new QuizAttemptResult.AnswerResult(q.getId(),answer,g.correct(),g.feedback()));}attempt.finish(correct);attempts.save(attempt);return new QuizAttemptResult(attempt.getId(),quizId,correct,quiz.getQuestions().size(),result);}
 private Grading grade(QuizQuestion q,String answer){if(answer.length()>3000)return new Grading(false,"Answer is too long.");if(answer.isBlank())return new Grading(false,"No answer was submitted.");if(q.getType()!=QuizQuestionType.SHORT_ANSWER)return new Grading(answer.equalsIgnoreCase(Objects.toString(q.getCorrectAnswer(),"").trim()),"Review the grounded source material for this question.");if(!llm.checkAvailability().isAvailable())return deterministic(q,answer,"AI grading is unavailable; this short answer was recorded for later review.");try{List<SearchResult> results=new ArrayList<>();for(QuizSource s:q.getSources()){var c=chunks.findById(s.getChunkId()).orElse(null);if(c!=null)results.add(new SearchResult(c.getDocument().getId(),c.getId(),c.getDocument().getOriginalFilename(),c.getChunkIndex(),c.getContent(),1d,c.getStartPage(),c.getEndPage(),List.of()));}var context=builder.build(results,12000);var parsed=parser.parse(llm.generate(prompts.buildShortAnswerGradingPrompt(q.getPrompt(),answer,q.getReferenceAnswer(),context.text())).content(),ShortAnswerGradingLlmResponse.class);Set<String> valid=context.sources().stream().map(GroundedSource::sourceId).collect(Collectors.toSet());if(parsed.feedback()==null||parsed.feedback().isBlank()||parsed.sourceIds().isEmpty()||parsed.sourceIds().stream().anyMatch(x->!valid.contains(x)))return deterministic(q,answer,"The AI grading response could not be validated; the answer was recorded.");return new Grading(parsed.correct(),parsed.feedback());}catch(RuntimeException ex){return deterministic(q,answer,"AI grading was unavailable; the answer was recorded safely.");}}
 private Grading deterministic(QuizQuestion q,String answer,String feedback){Set<String> ref=words(q.getReferenceAnswer()),given=words(answer);long overlap=given.stream().filter(ref::contains).count();return new Grading(!ref.isEmpty()&&overlap>=Math.max(1,Math.min(3,ref.size()/3)),feedback);}
 private Set<String> words(String value){return Arrays.stream(Objects.toString(value,"").toLowerCase(Locale.ROOT).split("[^a-z0-9]+" )).filter(x->x.length()>3).collect(Collectors.toSet());} private record Grading(boolean correct,String feedback){}
}
